"""Native ET vacuum comparisons: unchanged compiled GPU thorns, explicit differences."""
from pathlib import Path
import hashlib,json,math
H=Path(__file__).resolve().parent;out=H/'inputs';out.mkdir(exist_ok=True)
plan=[]
for kind,n,D,J,target in [('stationary',64,200.,0.,500.),('spinning',64,200.,.5,500.),('quasicircular',32,128.,0.,300.)]:
 binary=kind=='quasicircular';b=3.257 if binary else 1.;mp=.483 if binary else 1.;mm=.483 if binary else 0.;offset=0. if binary else -b;pt=-.133 if binary else 0.;h=2*D/n/256;dt=.2*h
 # CarpetX vertex fields: offset the outer box by half the finest cell for an isolated
 # punctures, so they remain off the y=z=0 vertices as in the PANGU cell-centred grid.
 shift=h/2
 thorns='ADMBaseX BoxInBox CarpetX CoordinatesX IOUtil ODESolvers TmunuBaseX TwoPuncturesX Z4c NewRadX AEILocalInterp AHFinderDirect SphericalSurface PunctureTracker'
 if binary:thorns+=' Weyl Multipole'
 lines=[f'ActiveThorns = "{thorns}"','Cactus::cctk_show_schedule = no','Cactus::presync_mode = "mixed-error"','CarpetX::verbose = no','CarpetX::poison_undefined_values = no','CarpetX::use_subcycling = no','CarpetX::ghost_size = 3','CarpetX::max_num_levels = 9','CarpetX::regrid_every = 16' if binary else 'CarpetX::regrid_every = 1000000000','CarpetX::regrid_error_threshold = 0.9','CarpetX::prolongation_type = "ddf"','CarpetX::prolongation_order = 5','CarpetX::interpolation_order = 4','CarpetX::refine_grid_layout = no','CarpetX::dtfac = 0.2','ODESolvers::method = "RK4"','BoxInBox::num_regions = '+str(2 if binary else 1)]
 for axis in 'xyz':lines += [f'CarpetX::{axis}min = {-D+shift:.17g}',f'CarpetX::{axis}max = {D+shift:.17g}',f'CarpetX::ncells_{axis} = {n}',f'CarpetX::max_grid_size_{axis} = 32',f'CarpetX::blocking_factor_{axis} = 1',f'CarpetX::boundary_{axis} = "neumann"',f'CarpetX::boundary_upper_{axis} = "neumann"']
 for i,x in enumerate([b,-b] if binary else [0.]):
  radii=[-1]+[D/2**(level-1) for level in range(1,9)]
  lines += [f'BoxInBox::shape_{i+1} = "cube"',f'BoxInBox::num_levels_{i+1} = 9',f'BoxInBox::position_x_{i+1} = {x}',f'BoxInBox::position_y_{i+1} = 0',f'BoxInBox::position_z_{i+1} = 0',f'BoxInBox::radius_{i+1} = ['+', '.join(map(str,radii))+']',f'PunctureTracker::track[{i}] = yes',f'PunctureTracker::initial_x[{i}] = {x}']
 lines += ['PunctureTracker::track_boxes = yes' if binary else 'PunctureTracker::track_boxes = no','PunctureTracker::interp_order = 4','ADMBaseX::initial_data = "TwoPunctures"','ADMBaseX::initial_lapse = "W"','ADMBaseX::initial_shift = "zero"','ADMBaseX::initial_dtlapse = "zero"','ADMBaseX::initial_dtshift = "zero"',f'TwoPuncturesX::par_b = {b}',f'TwoPuncturesX::center_offset[0] = {offset}',f'TwoPuncturesX::par_m_plus = {mp}',f'TwoPuncturesX::par_m_minus = {mm}','TwoPuncturesX::give_bare_mass = yes',f'TwoPuncturesX::par_P_plus[1] = {pt}',f'TwoPuncturesX::par_P_minus[1] = {-pt}',f'TwoPuncturesX::par_S_plus[2] = {J}','TwoPuncturesX::grid_setup_method = "Taylor expansion"','TwoPuncturesX::npoints_A = 30','TwoPuncturesX::npoints_B = 30','TwoPuncturesX::npoints_phi = 16','TwoPuncturesX::Newton_tol = 1e-10','TwoPuncturesX::Newton_maxit = 10','TwoPuncturesX::TP_epsilon = 1e-12','TwoPuncturesX::TP_Tiny = 1e-12','Z4c::calc_ADM_vars = yes','Z4c::calc_ADMRHS_vars = '+('yes' if binary else 'no'),'Z4c::calc_constraints = yes','Z4c::kappa1 = 0.02','Z4c::kappa2 = 0','Z4c::f_mu_L = 2','Z4c::f_mu_S = 1','Z4c::eta = 2','Z4c::veta_central = 2','Z4c::veta_outer = 2','Z4c::epsdiss = '+('0.32' if binary else '0.1'),'Z4c::chi_floor = '+('1e-6' if binary else '1e-12'),'Z4c::alphaG_floor = '+('1e-8' if binary else '1e-10'),'Z4c::boundary_conditions = "NewRadX"','IO::out_dir = "output"','IO::parfile_write = no','IO::checkpoint_ID = no','IO::checkpoint_on_terminate = no','CarpetX::out_metadata = no','CarpetX::out_norm_vars = "Z4c::HC Z4c::MtC ADMBaseX::alp"','CarpetX::out_norm_omit_unstable = yes','CarpetX::out_tsv_vars = "ADMBaseX::metric ADMBaseX::curv ADMBaseX::alp Z4c::HC Z4c::MtC"','AHFinderDirect::N_horizons = '+str(3 if binary else 1),'AHFinderDirect::move_origins = yes','AHFinderDirect::reshape_while_moving = yes','AHFinderDirect::predict_origin_movement = yes','AHFinderDirect::geometry_interpolator_name = "CarpetX"','AHFinderDirect::geometry_interpolator_pars = "order=4"','AHFinderDirect::surface_interpolator_name = "Lagrange polynomial interpolation"','AHFinderDirect::surface_interpolator_pars = "order=3"','AHFinderDirect::max_Newton_iterations__initial = 100','AHFinderDirect::max_Newton_iterations__subsequent = 50','AHFinderDirect::output_BH_diagnostics = yes','AHFinderDirect::output_h_every = 0','SphericalSurface::nsurfaces = '+str(3 if binary else 1),'SphericalSurface::maxntheta = 66','SphericalSurface::maxnphi = 124']
 for i,x in enumerate([b,-b,0.] if binary else [0.]):
  k=i+1;radius=.4 if binary and i<2 else 1. if binary else .5
  lines += [f'AHFinderDirect::initial_guess_method[{k}] = "coordinate sphere"',f'AHFinderDirect::initial_guess__coord_sphere__radius[{k}] = {radius}',f'AHFinderDirect::initial_guess__coord_sphere__x_center[{k}] = {x}',f'AHFinderDirect::origin_x[{k}] = {x}',f'AHFinderDirect::max_allowable_horizon_radius[{k}] = {8 if i==2 else 3}',f'AHFinderDirect::which_surface_to_store_info[{k}] = {i}',f'AHFinderDirect::set_mask_for_individual_horizon[{k}] = no',f'AHFinderDirect::reset_horizon_after_not_finding[{k}] = yes',f'SphericalSurface::ntheta[{i}] = 41',f'SphericalSurface::nphi[{i}] = 80',f'SphericalSurface::nghoststheta[{i}] = 2',f'SphericalSurface::nghostsphi[{i}] = 2']

 if binary:
  lines += ['AHFinderDirect::find_after_individual[3] = 1000','Multipole::interpolator_name = "CarpetX"','Multipole::interpolator_pars = "order=4"','Multipole::integration_method = "Simpson"','Multipole::nradii = 3','Multipole::radius[0] = 30','Multipole::radius[1] = 40','Multipole::radius[2] = 50','Multipole::ntheta = 40','Multipole::nphi = 80','Multipole::l_max = 4','Multipole::variables = "Weyl::Psi4re{sw=-2 cmplx=\'Weyl::Psi4im\' name=\'Psi4\'}"','Multipole::output_tsv = yes','Multipole::output_hdf5 = no']
 case=dict(id=kind+'_n'+str(n),kind=kind,n=n,domain_half_extent=D,finest_h=h,expected_dt=dt,target=target,J=J,required_initial_horizons=2 if binary else 1,physics='Nonspinning Bowen-York QC binary b3.257,m+/-0.483,Py-/+0.133' if binary else 'Isolated Bowen-York puncture bare mass1, Jz='+str(J),differences=['Native ET gauge has no PANGU slow-start lapse term; waveform time/phase alignment and initial-data error budget required','Independent native spectral initial data and AMR boxes; no identical-grid performance claim']+(['Outer box shifted by half finest cell to keep isolated puncture off vertex points','Zero-mass secondary spectral focus, center_offset shifts physical puncture to origin'] if not binary else ['Native upstream QC chi_floor=1e-6, alphaG_floor=1e-8 and epsdiss=0.32; outer box offset by half finest cell; puncture tracking and finite checks retained']),inputs={})
 for mode in ['admission','formal']:
  tail=['Cactus::terminate = "iteration"','Cactus::cctk_itlast = 64'] if mode=='admission' else ['Cactus::terminate = "time"',f'Cactus::cctk_final_time = {target}']
  cadence=1 if mode=='admission' else max(1,round(.1/dt));ahcad=32 if mode=='admission' else max(1,round(.5/dt))
  tail += [f'CarpetX::out_norm_every = {cadence}',f'IO::out_every = {64 if mode=="admission" else max(1,round(5/dt))}',f'AHFinderDirect::find_every = {ahcad}']
  if binary:tail += [f'Multipole::out_every = {cadence}']
  path=out/(case['id']+'_'+mode+'.par');path.write_text('# Native compiled ET GPU comparison; physical acceptance remains pending.\n'+'\n'.join(lines+tail)+'\n');case['inputs'][mode]=dict(file=path.name,sha256=hashlib.sha256(path.read_bytes()).hexdigest())
 plan.append(case)
(H/'PLAN.json').write_text(json.dumps(dict(cases=plan,status='native_inputs_prepared_GPU_admission_required'),indent=2));print([(c['id'],c['target'],c['finest_h']) for c in plan])
